def transform(grid):
    """Recolor any complete monochrome row or column with color 2."""
    out = [list(row) for row in grid]
    if not out:
        return out
    h, w = len(out), len(out[0])
    marked = set()
    for r, row in enumerate(grid):
        if row and all(v == row[0] for v in row):
            marked.update((r, c) for c in range(w))
    for c in range(w):
        v = grid[0][c]
        if all(grid[r][c] == v for r in range(h)):
            marked.update((r, c) for r in range(h))
    for r, c in marked:
        out[r][c] = 2
    return out
